  filter: drop-shadow(var(--layer-shadow-x) var(--layer-shadow-y) var(--layer-shadow-blur) var(--layer-shadow-color));
}

.ticket-frame-layer.canvas-selected,
.heading-layer.canvas-selected,
.metadata-layer.canvas-selected,
.route-layer.canvas-selected,
.stub-print-layer.canvas-selected { outline-offset: -5px; }
.exporting-ticket .canvas-selected { outline: 0 !important; box-shadow: none !important; }
.exporting-ticket .resize-handle { display: none !important; }
.exporting-ticket .ticket { filter: none !important; }

@media (max-width: 1180px) {
  .workspace { grid-template-columns: 220px minmax(460px, 1fr) 300px; }
  .canvas-toolbar { grid-template-columns: auto 1fr; min-height: 84px; }
  .zoom-control { grid-column: 2; }
  .rotation-control { grid-column: 2; }
}

@media (max-width: 780px) {
  .ticket-viewport { padding: 72px 36px; }
  .canvas-toolbar { grid-template-columns: 1fr; }
  .zoom-control,
  .rotation-control { grid-column: auto; width: min(280px, 100%); }
}

/* v9 — compact passage atelier */
:root {
  --ui-bg: #e9ded2;
  --ui-surface: #fbf7f0;
  --ui-panel: #fbf7f0;
  --ui-soft: #f3ece4;
  --ui-soft-2: #eadbd1;
  --ui-text: #3d302b;
  --ui-muted: #8b756a;
  --ui-dark: #3d302b;
  --ui-accent: #a8615c;
  --ui-line: rgba(104, 75, 64, .16);
  --ui-hover: rgba(168, 97, 92, .08);
  --ui-focus: rgba(168, 97, 92, .52);
  --ui-glass: rgba(251, 247, 240, .94);
}

body.ui-dark .app-shell {
  --ui-bg: #211c1a;
  --ui-surface: #2b2421;
  --ui-panel: #2b2421;
  --ui-soft: #352d29;
  --ui-soft-2: #453733;
  --ui-text: #f1e6d8;
  --ui-muted: #ae9688;
  --ui-dark: #f1e6d8;
  --ui-accent: #d59184;
  --ui-line: rgba(238, 218, 199, .13);
  --ui-hover: rgba(213, 145, 132, .1);
  --ui-focus: rgba(213, 145, 132, .58);
  --ui-glass: rgba(43, 36, 33, .94);
}

/* Template library */
.template-entry {
  background:
    radial-gradient(circle at 78% 12%, #fff7ea 0, #f2dfcb 34%, transparent 62%),
    linear-gradient(145deg, #d8c0a7, #efe0cf 52%, #d8c0aa);
}

.template-entry::before {
  display: block;
  width: 48vw;
  height: 48vw;
  background: radial-gradient(circle, #fffaf0 0 2px, transparent 2.5px) 0 0 / 18px 18px;
  opacity: .16;
}

.entry-shell {
  grid-template-columns: 210px minmax(0, 1fr);
  width: min(1180px, calc(100% - 48px));
  min-height: 100vh;
  margin: 0 auto;
  padding: 38px 0;
}

.entry-sidebar {
  position: relative;
  min-height: calc(100vh - 76px);
  padding: 18px 26px 18px 0;
  color: #745147;
}

.entry-brand { gap: 9px; }
.entry-brand::before { width: 42px; height: 1px; margin-bottom: 10px; background: #a8615c; }
.entry-brand strong { font: 600 24px/1 Cinzel, var(--serif); letter-spacing: .025em; }
.entry-brand span,
.entry-side-meta,
.entry-credit { color: #94776b; }

.entry-main {
  align-self: center;
  padding: 46px 0 56px 44px;
}

.entry-heading {
  align-items: flex-end;
  margin-bottom: 26px;
  padding: 0;
  box-shadow: none;
}

.entry-heading span { color: #a8615c; }
.entry-heading h1 {
  margin-top: 10px;
  color: #744740;
  font: 500 clamp(30px, 4vw, 48px)/.98 Cinzel, var(--serif);
  letter-spacing: -.035em;
}
.entry-heading p { max-width: 260px; color: #8b7064; font: 13px/1.6 var(--serif); text-align: right; }

.entry-options { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
.entry-card { padding: 0; color: #66463e; }
.entry-preview {
  aspect-ratio: 4 / 3;
  overflow: visible;
  border-radius: 18px;
  background: rgba(255, 248, 238, .34);
  box-shadow: inset 0 0 0 1px rgba(135, 91, 70, .08);
  transition: background .2s ease, transform .2s ease;
}
.entry-card:hover .entry-preview { background: rgba(255, 249, 240, .62); transform: translateY(-3px); }
.entry-card:hover .entry-card-copy strong { color: #9a5752; text-decoration: none; }
.template-thumb { box-shadow: 0 20px 34px #65462d25, 0 3px 0 #b99775; }
.thumb-train { width: 91%; }
.entry-card-copy { min-height: 48px; padding: 12px 4px 0; }
.entry-card-copy strong { color: #66463e; font-family: Cinzel, var(--serif); letter-spacing: .03em; transition: color .16s ease; }
.entry-card-copy em { color: #a8615c; }

/* Compact command bar */
.topbar {
  min-height: 52px;
  height: 52px;
  padding: 0 14px;
  border-bottom: 1px solid var(--ui-line);
  background: var(--ui-glass);
  box-shadow: none;
  backdrop-filter: blur(14px);
}

.brand h1 { color: var(--ui-accent); font: 600 14px/1 Cinzel, var(--serif); letter-spacing: .04em; }
.brand p { letter-spacing: .12em; }
.panel-toggles { display: flex; gap: 2px; margin-left: 14px; }
.panel-toggle,
.top-actions .icon-btn {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border-radius: 50%;
  color: var(--ui-muted);
  font-size: 14px;
}
.panel-toggle:hover,
.panel-toggle[aria-pressed="true"],
.top-actions .icon-btn:hover { background: var(--ui-soft); color: var(--ui-accent); }
.document-state { gap: 9px; margin-left: 16px; }
.document-state strong { color: var(--ui-text); letter-spacing: .04em; }
.top-actions { gap: 13px; }
.top-actions .btn.text { color: var(--ui-muted); font-weight: 600; }
.top-actions .btn.text:hover { color: var(--ui-accent); }
.top-actions .import-json-action {
  padding: 7px 10px;
  border: 1px solid var(--ui-line);
  border-radius: 3px;
  color: var(--ui-text);
  font-weight: 750;
}
.top-actions .import-json-action:hover,
.top-actions .import-json-action:focus-visible {
  border-color: var(--ui-accent);
  color: var(--ui-accent);
}

.export-menu { position: relative; }
.export-menu summary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 30px;
  padding: 5px 0;
  color: var(--ui-text);
  cursor: pointer;
  font-size: var(--type-meta);
  font-weight: 800;
  line-height: 1;
  list-style: none;
}
.export-menu summary::-webkit-details-marker { display: none; }
.export-menu summary::after {
  content: "";
  display: block;
  flex: 0 0 auto;
  width: 5px;
  height: 5px;
  margin-top: -3px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  color: var(--ui-muted);
  transform: rotate(45deg);
  transform-origin: center;
  transition: transform .15s ease, margin-top .15s ease;
}
.export-menu[open] summary::after { margin-top: 3px; transform: rotate(225deg); }
.export-menu-popover {
  position: absolute;
  top: 35px;
  right: -4px;
  z-index: 90;
  width: 214px;
  padding: 8px 8px 40px;
  border: 1px solid var(--ui-line);
  border-radius: 13px;
  background: var(--ui-surface);
  box-shadow: 0 18px 48px #3f261d2b;
}
.export-menu-popover > .btn {
  display: grid;
  grid-template-columns: 48px 1fr;
  width: 100%;
  padding: 9px 10px;
  border-radius: 8px;
  color: var(--ui-text);
  text-align: left;
}
.export-menu-popover > .btn:hover { background: var(--ui-soft); color: var(--ui-accent); }
.export-menu-popover > .btn strong { font: 700 11px var(--mono); }
.export-menu-popover > .btn span { color: var(--ui-muted); font-size: 11px; font-weight: 500; }
.export-menu-popover .export-help-button { position: absolute; right: 13px; bottom: 12px; }
.export-menu-popover .export-help { top: 0; right: calc(100% + 9px); }

/* Editor shell */
.workspace {
  grid-template-columns: 206px minmax(420px, 1fr) 282px;
  gap: 0;
  height: calc(100vh - 52px);
  padding: 0;
  background: var(--ui-bg);
  transition: grid-template-columns .22s ease;
}
.layers-panel,
.editor-panel,
.canvas-area { background: var(--ui-surface); }
.layers-panel { border-right: 1px solid var(--ui-line); transition: opacity .16s ease; }
.editor-panel { border-left: 1px solid var(--ui-line); transition: opacity .16s ease; }
body.layers-collapsed .workspace { grid-template-columns: 0 minmax(420px, 1fr) 282px; }
body.editor-collapsed .workspace { grid-template-columns: 206px minmax(420px, 1fr) 0; }
body.layers-collapsed.editor-collapsed .workspace { grid-template-columns: 0 minmax(420px, 1fr) 0; }
body.layers-collapsed .layers-panel,
body.editor-collapsed .editor-panel { opacity: 0; pointer-events: none; }

/* Flat, dense layer list */
.layers-title { padding: 15px 13px 9px; }
.layers-title span { color: var(--ui-accent); letter-spacing: .14em; }
.layers-title h2 { margin-top: 4px; font-size: 18px; letter-spacing: -.035em; }
.layer-list { gap: 0; padding: 3px 7px 6px; }
.layer-row {
  grid-template-columns: minmax(0, 1fr) 23px 23px;
  min-height: 37px;
  border-radius: 7px;
  background: transparent;
}
.layer-row:hover { background: var(--ui-hover); }
.layer-row.selected { background: var(--ui-soft); box-shadow: inset 2px 0 var(--ui-accent); }
.layer-row.drop-before { box-shadow: inset 0 2px var(--ui-accent); }
.layer-row.drop-after { box-shadow: inset 0 -2px var(--ui-accent); }
.layer-select { grid-template-columns: 23px minmax(0, 1fr); gap: 5px; padding: 4px 3px 4px 7px; }
.layer-select i {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: transparent;
  color: var(--ui-muted);
  font-size: 9px;
}
.layer-row.selected .layer-select i { color: var(--ui-accent); }
.layer-select strong { font-size: 11px; font-weight: 650; }
.layer-select small { display: none; }
.layer-action { width: 22px; height: 30px; color: var(--ui-muted); opacity: 0; transition: opacity .14s ease, color .14s ease; }
.layer-action::before { width: 14px; height: 14px; mask-size: 14px; }
.layer-row:hover .layer-action,
.layer-row.selected .layer-action,
.layer-row:focus-within .layer-action { opacity: .75; }
.layer-action:hover { color: var(--ui-accent); opacity: 1; }
.layer-order-controls {
  gap: 2px;
  margin: 0 8px;
  padding: 7px 0 9px;
  border: 0;
  border-top: 1px solid var(--ui-line);
}
.layer-order-controls button {
  height: 26px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--ui-muted);
}
.layer-order-controls button:hover { background: var(--ui-soft); color: var(--ui-accent); }

/* Contextual inspector */
.tabs { gap: 19px; min-height: 43px; padding: 15px 15px 7px; }
.tabs button { position: relative; font-size: 11px; letter-spacing: .04em; }
.tabs button.active { color: var(--ui-accent); }
.tabs button.active::after { content: ""; position: absolute; right: 0; bottom: -7px; left: 0; height: 2px; border-radius: 2px; background: var(--ui-accent); }
.panel-scroll { padding: 13px 16px 34px; }
.inspector-heading { display: flex; align-items: baseline; justify-content: space-between; margin: 0 0 15px; }
.inspector-heading span { color: var(--ui-accent); letter-spacing: .12em; }
.inspector-heading h2 { margin: 0; font-size: 20px; letter-spacing: -.035em; }
.field-label,
.control-label { margin: 13px 0 5px; color: var(--ui-muted); font-size: 11px; }
input,
textarea {
  min-height: 34px;
  padding: 8px 9px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: var(--ui-soft);
  transition: border-color .15s ease, background .15s ease;
}
textarea { line-height: 1.55; }
input:hover,
textarea:hover { background: var(--ui-soft-2); }
input:focus,
textarea:focus { border-color: var(--ui-focus); background: var(--ui-surface); }
.font-list { display: flex; flex-wrap: wrap; gap: 1px 13px; }
.font-list button {
  position: relative;
  width: auto;
  padding: 6px 0 5px;
  background: transparent;
  font-size: 11px;
}
.font-list button:hover { color: var(--ui-text); }
.font-list button.selected { background: transparent; color: var(--ui-accent); }
.font-list button.selected::after { content: ""; position: absolute; right: 0; bottom: 2px; left: 0; height: 1px; background: currentColor; }
.compact-grid,
.metric-grid { gap: 7px; margin-top: 13px; }
.compact-grid input { height: 35px; }
.color-control,
.switch-row { padding: 7px 0; background: transparent; }
.upload-zone { min-height: 42px; border: 1px dashed var(--ui-focus); border-radius: 9px; background: transparent; }
.upload-zone:hover { background: var(--ui-soft); }
.segmented { gap: 14px; margin-bottom: 14px; }
.segmented button { position: relative; }
.segmented button.active { color: var(--ui-accent); }
.range-field { margin: 13px 0; }
.range-field > span { margin-bottom: 7px; }
.image-position-controls,
.shadow-inspector { border-top-color: var(--ui-line); }
.position-inspector { margin-top: 18px; }
.shadow-inspector { margin-top: 16px; padding-top: 15px; }
.shadow-angle-dial { width: 68px; height: 68px; border-color: var(--ui-line); background-color: var(--ui-soft); }
.shadow-direction { grid-template-columns: 72px 1fr; gap: 10px; }
.motion-list { gap: 2px; }
.motion-list button { padding: 9px 2px; border-radius: 7px; background: transparent; }
.motion-list button.selected { background: var(--ui-soft); color: var(--ui-accent); }

/* Canvas becomes the visual center */
.canvas-area { position: relative; display: block; overflow: hidden; }
.ticket-scale { display: block; }
.ticket-view-transform {
  position: absolute;
  top: 50%;
  left: 50%;
  transform-origin: center;
}
.canvas-toolbar {
  position: absolute;
  top: 12px;
  left: 50%;
  z-index: 30;
  display: flex;
  grid-template-columns: none;
  align-items: center;
  gap: 10px;
  width: max-content;
  max-width: calc(100% - 24px);
  min-height: 38px;
  padding: 5px 9px;
  border: 1px solid var(--ui-line);
  border-radius: 999px;
  background: var(--ui-glass);
  box-shadow: 0 10px 30px #4b30221f;
  backdrop-filter: blur(14px);
  transform: translateX(-50%);
}
.canvas-toolbar > #canvasSize { display: none; }
.side-switch { gap: 2px; padding: 2px; border-radius: 999px; background: var(--ui-soft); }
.side-switch button { min-width: 48px; padding: 5px 9px; border-radius: 999px; font-size: 10px; }
.side-switch button.active { background: var(--ui-text); color: var(--ui-surface); }
.postcard-top-switch {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  border-radius: 2px;
  background: var(--ui-soft);
}
.postcard-top-switch[hidden] { display: none !important; }
.postcard-top-switch > span {
  padding: 0 6px;
  color: var(--ui-muted);
  font: 800 8px/1 var(--mono);
  letter-spacing: .14em;
}
.postcard-top-switch button {
  min-width: 44px;
  padding: 5px 8px;
  border: 0;
  border-radius: 2px;
  background: transparent;
  color: var(--ui-muted);
  font: 700 10px/1 var(--sans);
}
.postcard-top-switch button.active { background: var(--ui-text); color: var(--ui-surface); }
.zoom-control,
.rotation-control {
  display: flex;
  grid-template-columns: none;
  align-items: center;
  gap: 3px;
  width: auto;
  min-width: 0;
}
.zoom-control::before,
.rotation-control::before { content: ""; width: 1px; height: 17px; margin: 0 5px 0 1px; background: var(--ui-line); }
.zoom-control input,
.rotation-control input { display: none; }
.zoom-control button,
.rotation-control button { display: grid; place-items: center; width: 25px; height: 25px; border-radius: 50%; }
.zoom-control button:hover,
.rotation-control button:hover { background: var(--ui-soft); color: var(--ui-accent); }
.zoom-control output,
.rotation-control output { width: 39px; color: var(--ui-text); font-size: 10px; text-align: center; }
.zoom-presets { gap: 0; margin-left: 1px; }
.zoom-control .zoom-preset { width: auto; padding: 0 7px; border-radius: 999px; color: var(--ui-muted); font-size: 10px; }
#zoomActual { display: none; }
.stage {
  position: absolute;
  inset: 0;
  min-height: 0;
  background-color: #dfd0bf;
  background-image:
    radial-gradient(circle at 52% 42%, #f6ead9 0, #eadcca 39%, transparent 69%),
    linear-gradient(135deg, #d6c2ac, #eadccb 52%, #d0baa2);
  background-size: auto;
  scrollbar-color: #b89f8b transparent;
}
body.ui-dark .stage {
  background-color: #251e1b;
  background-image: radial-gradient(circle at 52% 42%, #4a3c35 0, #302622 46%, #211a18 76%);
}
.ticket-viewport { padding: 72px 34px 54px; }
.canvas-status {
  position: absolute;
  bottom: 11px;
  left: 50%;
  z-index: 25;
  width: auto;
  min-width: 250px;
  height: 28px;
  padding: 0 11px;
  border: 1px solid var(--ui-line);
  border-radius: 999px;
  background: var(--ui-glass);
  box-shadow: 0 7px 22px #4b302216;
  transform: translateX(-50%);
  backdrop-filter: blur(12px);
}

/* Reference-led paper ticket */
.ticket { filter: drop-shadow(0 22px 28px #62452c32); }
.ticket-face {
  background: #fff5e7;
  box-shadow: inset 0 0 0 1px #fffaf2, 0 3px 0 #ad9074;
}
.train .ticket-face {
  clip-path: polygon(
    0 7%, 2.5% 1%, 7% 0, 93% 0, 97.5% 1%, 100% 7%,
    100% 40%, 97.4% 46%, 97.4% 54%, 100% 60%,
    100% 93%, 97.5% 99%, 93% 100%, 7% 100%, 2.5% 99%, 0 93%,
    0 60%, 2.6% 54%, 2.6% 46%, 0 40%
  );
}
.train .block-main { inset: 0 28% 0 0; }
.train .block-stub,
.train .image-stub { inset: 0 0 0 72%; }
.train .ticket-front .image-main { top: 12%; left: 6.5%; width: 61%; height: 56%; }
.train .ticket-back .image-main { top: 13%; left: 47%; width: 20.5%; height: 72%; }
.train .image-main .block-image-frame,
.train .ticket-back .image-main .block-image-frame {
  border-radius: 44% 44% 14% 14% / 22% 22% 10% 10%;
  background:
    radial-gradient(circle at 70% 34%, #dfb274 0 4%, transparent 23%),
    linear-gradient(135deg, #486c73, #7b5b72 38%, #a86d58 62%, #d4a45f);
  box-shadow: inset 0 0 0 1px #6c403d4f;
}
.image-placeholder { color: #fff7eb; text-shadow: 0 1px 10px #4a2b2b; }
.ticket-inner-frame {
  inset: 3.8% 3.2%;
  border-color: var(--ticket-accent-78);
