  box-shadow: inset 0 0 0 4px #fff8e7, inset 0 0 0 5px var(--ticket-accent-42);
}
.train .ticket-front .image-frame-main { top: 10.8%; left: 5.6%; width: 62.8%; height: 58.8%; }
.train .ticket-back .image-frame-main { top: 11.8%; left: 46.1%; width: 22.3%; height: 74.4%; }
.train .image-frame-main {
  border: 1px solid var(--ticket-accent-86);
  border-radius: 44% 44% 14% 14% / 22% 22% 10% 10%;
  box-shadow: inset 0 0 0 4px #fff8e7b8, 0 0 0 1px #b88a5c7d;
}
.train .image-frame-stub { top: 4.8%; right: 3.5%; bottom: 4.8%; width: 21.4%; border-color: var(--ticket-accent-42); border-radius: 8px; }
.image-frame-main::before,
.image-frame-main::after { width: 16px; height: 16px; }

.train .ticket-front .heading-layer .kicker {
  top: 20.5%;
  right: 4.8%;
  left: 74.8%;
  color: var(--ticket-muted);
  font-size: 5px;
  letter-spacing: .16em;
  text-align: center;
}
.train .ticket-front .ticket-title {
  top: 25%;
  right: 4.7%;
  left: 74.7%;
  color: var(--ticket-accent);
  font-size: 24px;
  font-weight: 500;
  line-height: .98;
  letter-spacing: -.035em;
  text-align: center;
}
.train .ticket-front .ticket-subtitle {
  top: 37%;
  right: 5%;
  left: 75%;
