}
.train .ticket-front .metadata-layer span { padding-top: 3px; text-align: center; }
.train .ticket-front .metadata-layer small { font-size: 4px; letter-spacing: .08em; }
.train .ticket-front .metadata-layer b { margin-top: 1px; font-size: 5px; white-space: nowrap; }
.route-layer .perforation { left: 72%; background-size: 8px 12px; opacity: .68; }
.train .ticket-front .route-layer .ticket-seal,
.train .ticket-front .stub-print-layer .rail-code { display: none; }
.train .ticket-front .stub-print-layer .stub-copy {
  top: 49%;
  right: 5.1%;
  bottom: 19%;
  width: 18.2%;
}
.train .ticket-front .stub-print-layer .stub-copy > small:first-child { font-size: 4px; }
.train .ticket-front .stub-print-layer .stub-copy em {
  width: 100%;
  padding: 6px 3px;
  border: 1px solid var(--ticket-accent-62);
