/* v13 — editorial index, independent free-position documents, rail-led ticket */
:root {
  --ui-bg: #d9d6cf;
  --ui-surface: #f7f5ef;
  --ui-soft: #ece9e2;
  --ui-soft-2: #e3e0d9;
  --ui-text: #181817;
  --ui-dark: #111110;
  --ui-muted: #706d67;
  --ui-accent: #df3f34;
  --ui-line: rgba(24, 24, 23, .17);
  --ui-hover: rgba(223, 63, 52, .07);
  --ui-focus: rgba(223, 63, 52, .55);
  --ui-glass: rgba(247, 245, 239, .96);
}

body.ui-dark {
  --ui-bg: #1d1d1b;
  --ui-surface: #272724;
  --ui-soft: #32322e;
  --ui-soft-2: #3a3a35;
  --ui-text: #f2efe7;
  --ui-dark: #fffdf5;
  --ui-muted: #aaa79f;
  --ui-accent: #ff5b4e;
  --ui-line: rgba(242, 239, 231, .15);
  --ui-hover: rgba(255, 91, 78, .1);
  --ui-focus: rgba(255, 91, 78, .62);
  --ui-glass: rgba(39, 39, 36, .96);
}

.sr-only {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.ticket-shapes { position: fixed; inset: 0; pointer-events: none; }

/* Editorial template index */
.template-entry {
