  height: calc(100vh - 48px);
  background: var(--ui-bg);
}
body.layers-collapsed .workspace { grid-template-columns: 0 minmax(420px, 1fr) 286px; }
body.editor-collapsed .workspace { grid-template-columns: 196px minmax(420px, 1fr) 0; }
body.layers-collapsed.editor-collapsed .workspace { grid-template-columns: 0 minmax(420px, 1fr) 0; }
.layers-panel,
.editor-panel { background: var(--ui-surface); }
.layers-title { padding: 13px 11px 8px; }
.layers-title span { color: var(--ui-accent); font-family: var(--mono); }
.layers-title h2 { margin-top: 2px; font-size: 17px; }
.layer-list { padding-inline: 5px; }
.layer-row { min-height: 34px; border-radius: 2px; }
