.compact-grid.three-up { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.compact-grid.three-up input { padding-inline: 6px; }
/* Compact rectangular tool strip */
.canvas-area { background: var(--ui-bg); }
.canvas-toolbar {
  top: 10px;
  gap: 6px;
  min-height: 40px;
  padding: 5px 6px;
