/* Source: styles/ticket-editor-v14.css */
/* Crisp preview, split text objects, rebuilt train and cinema faces. */
.ticket,
.ticket-view-transform { will-change: auto; }
.ticket { filter: none !important; }
.ticket-scale { isolation: isolate; }
.ticket-scale::before {
  content: "";
  position: absolute;
  inset: 12% 5% 4%;
  z-index: -1;
  border-radius: 18px;
  background: rgba(62, 47, 36, .24);
  filter: blur(22px);
  transform: translateY(16px);
  pointer-events: none;
}
.ticket-view-transform {
  text-rendering: geometricPrecision;
  -webkit-font-smoothing: antialiased;
}
.paper-texture {
  inset: 0;
  background-size: 1100px 1100px;
  filter: none;
  opacity: calc(var(--texture-strength) * .72);
}
.image-slot img { image-rendering: auto; }

/* One visual language for every canvas tool. */
.layout-control button,
.layout-control .toolbar-tool,
.zoom-control button,
.rotation-control button {
  display: grid;
  place-items: center;
  width: 26px;
  min-width: 26px;
  height: 26px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 2px;
  background: transparent;
  color: var(--ui-muted);
  font: 700 12px/1 var(--mono);
  box-shadow: none;
}
.layout-control button:hover,
.zoom-control button:hover,
.rotation-control button:hover {
  border-color: var(--ui-line);
  background: var(--ui-soft);
  color: var(--ui-text);
}
.layout-control .tool-mode.active {
  border-color: var(--ui-accent);
  background: var(--ui-soft);
  color: var(--ui-accent);
  box-shadow: none;
}
.layout-control .snap-toggle {
  display: flex;
  width: auto;
  min-width: 48px;
  height: 26px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 2px;
  background: transparent;
  color: var(--ui-muted);
}
.layout-control .snap-toggle:hover { border-color: var(--ui-line); background: var(--ui-soft); }
#resetPlacementBtn { font-size: 14px; }

/* The layer list now reflects the actual movable objects. */
.layer-row[hidden] { display: none !important; }
.heading-layer,
.metadata-layer,
.route-layer,
.stub-print-layer { pointer-events: none; }
.heading-layer > [data-canvas-layer],
.metadata-layer > [data-canvas-layer],
.route-layer > [data-canvas-layer],
