.details-layer > [data-canvas-layer],
.speaker-layer,
.back-copy-label,
.back-body-layer { pointer-events: auto; }
.route-art-layer { position: absolute; inset: 0; }
.route-art-layer > * { pointer-events: none; }
.speaker-layer,
.back-copy-label,
.back-body-layer {
  position: absolute;
