  margin: 0;
  user-select: none;
}
.speaker-layer { font-family: var(--sans); font-weight: 600; }
.back-copy-label { color: var(--ticket-accent); font: 700 8px var(--mono); letter-spacing: .16em; }
.back-body-layer { color: var(--ticket-muted); font: 400 12px/1.65 var(--sans); white-space: pre-line; word-break: keep-all; }
.ticket.freeform-mode [data-canvas-layer].freeform-movable { cursor: move; touch-action: none; }
.ticket [data-canvas-layer].canvas-selected:not(.ticket-block):not(.image-slot):not(.ticket-frame-layer) {
