  overflow: visible !important;
  overflow-clip-margin: 1em;
}
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-font-size-override,
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-font-size-override * {
  font-size: var(--layer-font-size) !important;
}
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-font-family-override,
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-font-family-override * {
  font-family: var(--layer-font-family) !important;
}
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-font-weight-override,
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-font-weight-override * {
  font-weight: var(--layer-font-weight) !important;
}
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-font-style-override,
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-font-style-override * {
  font-style: var(--layer-font-style) !important;
}
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-spacing-override,
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-spacing-override * {
  letter-spacing: var(--layer-letter-spacing, inherit) !important;
  line-height: var(--layer-line-height, inherit) !important;
}
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-text-align-override,
#ticket.ticket.ticket.ticket [data-canvas-layer].layer-text-align-override * {
  text-align: var(--layer-text-align) !important;
}

/* v125: full-width archive landing. The masthead now reads as a quiet brand
   strip followed by one decisive hero, while the catalog keeps its original
   buttons, specifications, keyboard focus and document-opening behavior. */
#templateEntry {
  overflow: auto;
  background: #f1eee7;
}
#templateEntry .entry-shell {
  display: block;
  width: 100%;
  max-width: none;
  min-height: 100vh;
  margin: 0;
  padding: 0;
}
#templateEntry .entry-masthead {
  position: relative;
  top: auto;
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(260px, .55fr);
  grid-template-rows: 88px clamp(292px, 20.5vw, 328px);
  min-height: 0;
  padding: 0;
  border: 0;
  background: #b45a50;
  color: #171313;
  overflow: hidden;
}
#templateEntry .entry-masthead .entry-brand {
  grid-column: 1 / -1;
  grid-row: 1;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: clamp(42px, 5.5vw, 88px);
  padding: 0 clamp(36px, 5vw, 80px);
  background: #f1eee7;
  color: #171313;
}
#templateEntry .entry-masthead .entry-brand::before { display: none; }
#templateEntry .entry-masthead .entry-brand strong {
  width: 78px;
  color: #171313;
  font: 800 15px/.88 Pretendard, sans-serif;
  letter-spacing: -.035em;
}
#templateEntry .entry-masthead .entry-brand span {
  color: #171313;
  font: 700 8px/1.35 var(--mono);
  letter-spacing: .08em;
}
#templateEntry .entry-masthead h1 {
  grid-column: 1;
  grid-row: 2;
  align-self: end;
  display: flex;
  flex-direction: column;
  gap: clamp(3px, .22vw, 5px);
  width: min-content;
  max-width: none;
  margin: 0;
  padding: 12px 0 24px clamp(36px, 4.4vw, 70px);
  color: #171313;
  font: 800 clamp(76px, 8.3vw, 136px)/.8 Pretendard, sans-serif;
  letter-spacing: -.085em;
}
#templateEntry .entry-masthead h1 > span,
#templateEntry .entry-masthead h1 > i { display: block; }
#templateEntry .entry-masthead h1 > i {
  font-family: "Noto Serif KR", serif;
  font-size: .76em;
  font-style: italic;
  font-weight: 400;
  /* Optically centre YOUR between CHOOSE and PASSAGE. The serif face carries
     much deeper vertical metrics than Pretendard, so with line-height .8 its
     glyphs sat 13.6px low - measured ink gaps 14.29px above against 0.68px
     below. Lifting it half that difference evens both gaps out, and the
     matching bottom margin keeps PASSAGE and the hero height untouched. The
     offset is in em, so it holds at every clamped headline size. */
  margin-top: -.075em;
  margin-bottom: .075em;
  letter-spacing: -.085em;
}
#templateEntry .entry-masthead h1 > span:last-child {
  font-size: .82em;
  letter-spacing: -.065em;
}
#templateEntry .entry-masthead p {
  grid-column: 2;
  grid-row: 2;
  align-self: end;
  justify-self: end;
  max-width: 250px;
  margin: 0;
  padding: 0 clamp(28px, 4.5vw, 72px) 24px 20px;
  color: #201b1a;
  font: 500 12px/1.65 Pretendard, sans-serif;
  text-align: right;
}
#templateEntry .entry-main {
  display: grid;
  grid-template-columns: minmax(230px, 30%) minmax(0, 1fr);
  gap: clamp(48px, 8vw, 132px);
  width: min(100%, 1592px);
  min-width: 0;
  margin: 0 auto;
  padding: 32px clamp(36px, 5vw, 80px) 76px;
  box-sizing: border-box;
}
#templateEntry .entry-meta {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  gap: 8px;
  min-width: 0;
  padding-top: 2px;
  color: #716b65;
  font: 700 8px/1.45 var(--mono);
  letter-spacing: .09em;
  text-align: left;
}
#templateEntry .entry-count {
  grid-column: 1;
  margin: 0;
  color: #716b65;
  font: 700 9px/1.2 var(--mono);
  letter-spacing: .12em;
}
#templateEntry .entry-version {
  grid-column: 1;
  color: #716b65;
  white-space: nowrap;
}
#templateEntry .entry-credit {
  grid-column: 1;
  display: block;
  margin: 0;
  color: #716b65;
  font: inherit;
  letter-spacing: inherit;
  text-align: left;
}
#templateEntry .entry-catalog { min-width: 0; }
#templateEntry .entry-list-label {
  display: flex;
  justify-content: space-between;
  margin: 0;
  padding: 0 0 24px;
  border: 0;
  box-shadow: none;
  color: #716b65;
  font: 700 8px/1 var(--mono);
  letter-spacing: .14em;
}
#templateEntry .entry-list-label b { color: #a75047; }
#templateEntry .entry-options { display: block; }
#templateEntry .entry-card {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) minmax(150px, 176px);
  gap: 26px;
  min-height: 178px;
  padding: 44px 0;
  border: 0;
  border-bottom: 1px solid rgba(23, 19, 19, .16);
  border-radius: 0;
  background: transparent;
  color: #171313;
  box-sizing: border-box;
  text-align: left;
  transition: background .16s ease, padding .16s ease;
}
#templateEntry .entry-card:first-child { border-top: 1px solid rgba(23, 19, 19, .16); }
#templateEntry .entry-card:last-child { border-bottom-color: rgba(23, 19, 19, .16); }
#templateEntry .entry-card:hover,
#templateEntry .entry-card:focus-visible {
  padding-right: 10px;
  padding-left: 10px;
  background: rgba(167, 80, 71, .065);
}
#templateEntry .entry-card:focus-visible {
  outline: 2px solid #a75047;
  outline-offset: -2px;
}
#templateEntry .entry-index {
  align-self: start;
  color: #b45a50;
  font: 700 29px/.9 var(--mono);
  letter-spacing: -.08em;
}
#templateEntry .entry-card-copy {
  align-self: stretch;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto auto;
  align-content: center;
  min-height: 88px;
  padding: 0;
}
#templateEntry .entry-card-copy small,
#templateEntry .entry-card-copy strong,
#templateEntry .entry-card-copy > span { grid-column: 1; }
#templateEntry .entry-card-copy small {
  grid-row: 1;
  color: #716b65;
  font: 700 8px/1.2 var(--mono);
  letter-spacing: .1em;
}
#templateEntry .entry-card-copy strong {
  grid-row: 2;
  margin-top: 9px;
  color: #171313;
  font: 800 clamp(27px, 2.2vw, 36px)/.92 Pretendard, sans-serif;
  letter-spacing: -.065em;
}
#templateEntry .entry-card-copy > span {
  grid-row: 3;
  margin-top: 11px;
  color: #65615b;
  font: 500 11px/1.45 Pretendard, sans-serif;
}
#templateEntry .entry-card-copy em {
  position: static;
  grid-column: 2;
  grid-row: 1 / 4;
  align-self: center;
  width: max-content;
  margin: 0 0 0 20px;
  padding: 0;
  color: #a75047;
  font: 800 10px/1.2 Pretendard, sans-serif;
  font-style: normal;
  letter-spacing: 0;
}
#templateEntry .entry-card:hover .entry-card-copy strong { color: #171313; text-decoration: none; }
#templateEntry .entry-card:hover .entry-card-copy em { text-decoration: underline; text-underline-offset: 3px; }
#templateEntry .entry-spec {
  align-self: center;
  display: grid;
  min-height: 88px;
  padding: 13px 0 10px 18px;
  border: 0;
  border-left: 1px solid rgba(23, 19, 19, .24);
  color: #716b65;
  font: 700 8px/1.2 var(--mono);
  font-style: normal;
  letter-spacing: .09em;
}
#templateEntry .entry-spec b { color: #171313; font-size: 9px; }
#templateEntry .entry-spec small { font-size: 8px; }
#templateEntry .entry-spec i { color: #a75047; font-size: 8px; font-style: normal; }

@media (max-width: 1100px) {
  #templateEntry .entry-main {
    grid-template-columns: 180px minmax(0, 1fr);
    gap: 42px;
    padding-inline: 34px;
  }
  #templateEntry .entry-card { grid-template-columns: 42px minmax(0, 1fr) 140px; gap: 18px; }
  #templateEntry .entry-card-copy em { margin-left: 12px; }
}

@media (max-width: 820px) {
  #templateEntry .entry-masthead {
    grid-template-columns: minmax(0, 1.45fr) minmax(210px, .55fr);
    grid-template-rows: 76px 300px;
  }
  #templateEntry .entry-masthead .entry-brand { padding-inline: 28px; }
  #templateEntry .entry-masthead h1 { padding: 12px 0 22px 28px; font-size: clamp(68px, 13vw, 104px); }
  #templateEntry .entry-masthead p { padding: 0 28px 22px 16px; }
  #templateEntry .entry-main { display: block; padding: 26px 28px 58px; }
  #templateEntry .entry-meta {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
    margin-bottom: 38px;
  }
  #templateEntry .entry-count { grid-column: 1; }
  #templateEntry .entry-version,
  #templateEntry .entry-credit { grid-column: 1; text-align: left; }
  #templateEntry .entry-card { grid-template-columns: 42px minmax(0, 1fr) 146px; }
}

@media (max-width: 700px) {
  #templateEntry .entry-masthead {
    grid-template-columns: 1fr;
    grid-template-rows: 72px 350px;
  }
  #templateEntry .entry-masthead .entry-brand { padding-inline: 20px; }
  #templateEntry .entry-masthead h1,
  #templateEntry .entry-masthead p { grid-column: 1; grid-row: 2; }
  #templateEntry .entry-masthead h1 {
    align-self: start;
    padding: 22px 20px 0;
    font-size: clamp(64px, 18vw, 94px);
  }
  #templateEntry .entry-masthead p { align-self: end; padding: 0 20px 22px; }
  #templateEntry .entry-main { padding: 24px 20px 48px; }
  #templateEntry .entry-meta { display: grid; margin-bottom: 32px; }
  #templateEntry .entry-credit { margin-left: 0; text-align: left; }
  #templateEntry .entry-list-label { padding-bottom: 18px; }
  #templateEntry .entry-card {
    grid-template-columns: 34px minmax(0, 1fr);
    gap: 14px;
    min-height: 0;
    padding: 26px 0;
  }
  #templateEntry .entry-card:hover,
  #templateEntry .entry-card:focus-visible { padding-right: 6px; padding-left: 6px; }
  #templateEntry .entry-card-copy {
    grid-column: 2;
    display: flex;
    flex-direction: column;
    min-height: 0;
  }
  #templateEntry .entry-card-copy em { margin: 16px 0 0; }
  #templateEntry .entry-spec {
    grid-column: 2;
    grid-template-columns: repeat(3, auto);
    justify-content: space-between;
    gap: 12px;
    min-height: 0;
    margin-top: 14px;
    padding: 12px 0 0;
    border-top: 1px solid rgba(23, 19, 19, .18);
    border-left: 0;
  }
}

@media (max-width: 430px) {
  #templateEntry .entry-masthead .entry-brand { gap: 24px; }
  #templateEntry .entry-masthead .entry-brand strong { width: 68px; font-size: 13px; }
  #templateEntry .entry-masthead .entry-brand span { font-size: 7px; }
  #templateEntry .entry-masthead h1 { font-size: clamp(58px, 20vw, 82px); }
  #templateEntry .entry-credit { margin-left: 0; text-align: left; }
}

/* v139: browsing formats no longer scrolls the whole landing page. The hero
   masthead and the index sidebar stay put while only the format list scrolls
   inside its own column. Narrow or short viewports, where the stacked layout
   needs the page scroll to stay reachable, keep the original behavior.
   The hero itself keeps its original v125 proportions - the v140 experiment
   that shortened it was rolled back on request, so nothing in this block
   touches the masthead. */
@media (min-width: 821px) and (min-height: 620px) {
  #templateEntry { overflow: hidden; }
  #templateEntry .entry-shell {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
  }
  #templateEntry .entry-masthead { flex: 0 0 auto; }
  #templateEntry .entry-main {
    flex: 1 1 auto;
    min-height: 0;
    padding-bottom: 28px;
  }
  #templateEntry .entry-catalog {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: 0;
  }
  /* A small chevron pointing down, drawn in the catalog's own muted ink. It
     simply retires once the list is scrolled to the end - no motion. */
  #templateEntry .entry-catalog::after {
    position: absolute;
    bottom: 6px;
    left: 50%;
    width: 9px;
    height: 9px;
    margin-left: -5px;
    border-right: 1.5px solid #716b65;
    border-bottom: 1.5px solid #716b65;
    content: "";
    pointer-events: none;
    opacity: .7;
    transform: rotate(45deg);
    transition: opacity .18s ease;
  }
  #templateEntry .entry-catalog.is-scroll-end::after { opacity: 0; }
  #templateEntry .entry-list-label { flex: 0 0 auto; }
  #templateEntry .entry-options {
    flex: 1 1 auto;
    min-height: 0;
    /* Run-out so the last card never sits flush against the fold. */
    padding-bottom: 40px;
    overflow-y: auto;
    overscroll-behavior: contain;
    /* The list scrolls, but the bar itself stays out of the composition. */
    scrollbar-width: none;
    -ms-overflow-style: none;
  }
  #templateEntry .entry-options::-webkit-scrollbar { width: 0; height: 0; }
}


/* v129: the conductor-coupon table owns one real layer containing both
   vertical rules and the shared horizontal rule. The visible strokes are
   full CSS pixels so preview and PNG rasterization cannot drop a subpixel
   line; only the narrow rule hit areas receive pointer events. */
#ticket.train .ticket-front .metadata-layer > .metadata-field + .metadata-field,
#ticket.train .ticket-back .train-back-coupon-metadata > .metadata-field + .metadata-field {
  border-left: 0 !important;
}
#ticket.train .ticket-front .metadata-layer > .metadata-field::after,
#ticket.train .ticket-back .train-back-coupon-metadata > .metadata-field::after {
  content: none !important;
  display: none !important;
}
#ticket.train .ticket-front .metadata-layer > .train-coupon-meta-rules,
#ticket.train .ticket-back .train-back-coupon-metadata > .train-coupon-meta-rules {
  --coupon-meta-rule-ink: var(--layer-custom-color, var(--ticket-accent));
  position: absolute !important;
  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;
  z-index: var(--layer-z, 1) !important;
  display: block !important;
  width: 100% !important;
  min-width: 0 !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: visible !important;
  border: 0 !important;
  box-sizing: border-box !important;
  background: none !important;
  color: var(--coupon-meta-rule-ink) !important;
  pointer-events: none !important;
}
#ticket.train .train-coupon-meta-rules > .train-coupon-meta-rule {
  position: absolute;
  display: block;
  margin: 0;
  padding: 0;
  border: 0;
  box-sizing: border-box;
  background: transparent;
  pointer-events: auto;
  touch-action: none;
}
#ticket.train .train-coupon-meta-rules > .train-coupon-meta-rule::before {
  position: absolute;
  background: currentColor;
  content: "";
  pointer-events: none;
}
#ticket.train .train-coupon-meta-rules > .train-coupon-meta-rule-v {
  top: 0;
  bottom: 0;
  width: 7px;
}
#ticket.train .train-coupon-meta-rules > .train-coupon-meta-rule-v::before {
  top: 0;
  bottom: 0;
  left: 3px;
  width: 1px;
}
#ticket.train .train-coupon-meta-rules > .train-coupon-meta-rule-v1 {
  left: calc(33.333333% - 3.5px);
}
#ticket.train .train-coupon-meta-rules > .train-coupon-meta-rule-v2 {
  left: calc(66.666667% - 3.5px);
}
#ticket.train .train-coupon-meta-rules > .train-coupon-meta-rule-h {
  top: calc(43% - 3.5px);
  right: 0;
  left: 0;
  height: 7px;
}
#ticket.train .train-coupon-meta-rules > .train-coupon-meta-rule-h::before {
  top: 3px;
  right: 0;
  left: 0;
  height: 1px;
}

/* v127: compact, usable side-panel scrolling and an explicit visibility-only
   layer row. The Shadow row owns only an eye toggle, so it must not reserve or
   resurrect the drag/lock columns used by editable canvas objects. */
.layer-drag-grip[hidden] { display: none !important; }
.layer-row.visibility-only-layer,
.layer-row.visibility-only-layer.single-action {
  grid-template-columns: minmax(0, 1fr) 25px !important;
}
.layer-row.visibility-only-layer .layer-select,
.layer-row.visibility-only-layer .layer-select[aria-disabled="true"] {
  min-width: 0;
  color: var(--ui-text) !important;
  -webkit-text-fill-color: currentColor;
  cursor: default;
  opacity: 1 !important;
}
.layer-row.visibility-only-layer .layer-select i {
  display: grid;
  width: 20px;
  height: 20px;
  place-items: center;
  align-self: center;
}
.layer-row.visibility-only-layer .layer-select strong { display: block !important; }

.layer-list,
.editor-panel .panel-scroll {
  scrollbar-width: thin;
  scrollbar-color: #98938d transparent;
}
.layer-list::-webkit-scrollbar,
.editor-panel .panel-scroll::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}
.layer-list::-webkit-scrollbar-track,
.editor-panel .panel-scroll::-webkit-scrollbar-track { background: transparent; }
.layer-list::-webkit-scrollbar-thumb,
.editor-panel .panel-scroll::-webkit-scrollbar-thumb {
  min-height: 32px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: #98938d;
  background-clip: padding-box;
}
.layer-list::-webkit-scrollbar-thumb:hover,
.editor-panel .panel-scroll::-webkit-scrollbar-thumb:hover {
  background: var(--ui-text);
  background-clip: padding-box;
}
.layer-list::-webkit-scrollbar-button,
.editor-panel .panel-scroll::-webkit-scrollbar-button {
  display: none;
  width: 0;
  height: 0;
}
.editor-panel .panel-scroll {
  position: relative;
  z-index: 1;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto !important;
  overscroll-behavior: contain;
  pointer-events: auto !important;
  scrollbar-gutter: stable;
  touch-action: pan-y;
}

/* v128: compact snap controls, calmer partial-style actions, and enough
   toolbar width for every alignment mode without labels escaping buttons. */
.canvas-toolbar { max-width: calc(100% - 12px); }
.layout-control { flex: 0 0 auto; gap: 2px; }
.layout-control .snap-toggle,
.layout-control .smart-snap-toggle {
  display: grid;
  width: 42px;
  min-width: 42px;
  max-width: 42px;
  padding: 0;
  place-items: center;
  overflow: hidden;
  box-sizing: border-box;
  font: 700 8px/1 var(--mono);
  letter-spacing: 0;
  text-align: center;
  text-indent: 0;
  white-space: nowrap;
}
.layout-control .snap-toggle.active,
.layout-control .smart-snap-toggle.active {
  box-shadow: none !important;
}

.layer-text-inspector.active + .layer-style-inspector.active { margin-top: 11px; }
.partial-text-tools {
  gap: 2px;
  margin-top: 8px;
  padding: 0;
  border: 0;
  background: transparent;
}
.partial-text-tools.has-partial-style { border: 0; }
.partial-text-tools .text-btn {
  justify-self: start;
  width: auto;
  margin: 5px 0 0;
  padding: 5px 0;
  border: 0;
  background: transparent;
  color: var(--ui-muted);
  font: 650 var(--type-meta)/1.2 var(--sans);
}

/* v131: compact replacement-style layout examples and equal numeric controls. */
.layout-preset-controls {
  display: grid;
  gap: 5px;
  margin: 0 7px 6px;
  padding: 7px;
  border: 1px solid var(--ui-line);
  background: var(--ui-panel);
}
.layout-preset-controls[hidden] { display: none !important; }
.layout-preset-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  color: var(--ui-text);
  font: 750 9px/1 var(--sans);
  letter-spacing: 0;
}
.layout-preset-heading small {
  color: var(--ui-muted);
  font: inherit;
  letter-spacing: 0;
}
.layout-preset-action {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 48px;
  gap: 5px;
}
.layout-preset-action select,
.layout-preset-action button {
  min-width: 0;
  height: 28px;
  border: 1px solid var(--ui-line);
  border-radius: 2px;
  box-sizing: border-box;
  font: 650 9px/1.2 var(--sans);
}
.layout-preset-action select {
  width: 100%;
  padding: 0 24px 0 8px;
  background: var(--ui-soft);
  color: var(--ui-text);
}
.layout-preset-action button {
  padding: 0 7px;
  background: var(--ui-accent);
  color: #fff;
}
.layout-preset-action button:hover { filter: brightness(.94); }
.layout-preset-action button:disabled { cursor: default; opacity: .45; }
