  background: transparent;
  font: 600 8px/1.3 var(--sans);
  letter-spacing: .025em;
}

.ticket:is(.postcard, .cassette, .polaroid) .metadata-layer span {
  min-width: 0;
  border: 0;
  padding: 0;
}

.ticket:is(.postcard, .cassette, .polaroid) .metadata-layer small {
  color: var(--keepsake-accent);
  font: 700 6px/1.2 var(--mono);
  letter-spacing: .15em;
  text-transform: uppercase;
