/* ---------- Postcard + postage stamp ---------- */

.postcard .ticket-front .block-main {
  inset: 7% 35% 7% 0;
  border-radius: 2px;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, .68),
    0 2px 1px rgba(50, 39, 30, .12),
    0 13px 20px rgba(50, 39, 30, .15);
}

.postcard .ticket-front .block-stub {
  inset: 2.5% 0 2.5% 69%;
  box-shadow: 0 12px 20px rgba(47, 37, 28, .22);
  -webkit-mask:
    radial-gradient(circle at 0 9px, transparent 0 4px, #000 4.6px) left top / 100% 18px repeat-y,
    radial-gradient(circle at 100% 9px, transparent 0 4px, #000 4.6px) right top / 100% 18px repeat-y,
    radial-gradient(circle at 9px 0, transparent 0 4px, #000 4.6px) left top / 18px 100% repeat-x,
    radial-gradient(circle at 9px 100%, transparent 0 4px, #000 4.6px) left bottom / 18px 100% repeat-x;
  -webkit-mask-composite: source-in;
  mask:
    radial-gradient(circle at 0 9px, transparent 0 4px, #000 4.6px) left top / 100% 18px repeat-y,
    radial-gradient(circle at 100% 9px, transparent 0 4px, #000 4.6px) right top / 100% 18px repeat-y,
    radial-gradient(circle at 9px 0, transparent 0 4px, #000 4.6px) left top / 18px 100% repeat-x,
    radial-gradient(circle at 9px 100%, transparent 0 4px, #000 4.6px) left bottom / 18px 100% repeat-x;
  mask-composite: intersect;
}

.postcard .ticket-front .block-stub::after {
  content: "";
  position: absolute;
  inset: 9px;
  border: 1px solid var(--ticket-accent-42);
  pointer-events: none;
}

.postcard .ticket-front .image-main { display: none !important; }

.postcard .ticket-front .image-stub {
  inset: 12% 2.8% 17% 71.6%;
  z-index: 2;
}

.postcard .ticket-front .image-stub .block-image-frame,
.postcard .ticket-front .image-stub:not(.has-image) .block-image-frame {
