/* v82: actual postcard faces. Front and back are the only editable sources;
   Both is a projection of those same nodes, never a duplicated design. */
.ticket.postcard {
  width: min(900px, 86vw);
  aspect-ratio: 3 / 2;
  background: transparent !important;
  overflow: visible !important;
}
#ticket.postcard > .ticket-face {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  display: block !important;
  opacity: 0 !important;
  visibility: hidden !important;
  overflow: hidden !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  transform: none !important;
  rotate: none !important;
  pointer-events: none !important;
}
#ticket.postcard.postcard-view-front > .ticket-front,
#ticket.postcard.postcard-view-back > .ticket-back,
#ticket.postcard.postcard-view-both > .ticket-front,
#ticket.postcard.postcard-view-both > .ticket-back {
  opacity: 1 !important;
  visibility: visible !important;
}
#ticket.postcard.postcard-view-front > .ticket-front,
#ticket.postcard.postcard-view-back > .ticket-back { pointer-events: auto !important; }
#ticket.postcard.postcard-view-both > .ticket-front,
#ticket.postcard.postcard-view-both > .ticket-back {
  width: 100% !important;
  height: 100% !important;
  transform-origin: 50% 50% !important;
  -webkit-font-smoothing: antialiased;
  -webkit-backface-visibility: hidden !important;
  backface-visibility: hidden !important;
  will-change: transform;
  image-rendering: auto !important;
}
#ticket.postcard.postcard-view-both > .ticket-front *,
#ticket.postcard.postcard-view-both > .ticket-back * {
  image-rendering: auto !important;
}
#ticket.postcard.postcard-view-both > .ticket-front {
  inset: -18% auto auto -16% !important;
  transform: translateZ(0) rotate(-3.2deg) scale(.58) !important;
}
#ticket.postcard.postcard-view-both > .ticket-back {
